  "requirement_verdicts": [
    {
      "req": "REQ-2234-F1",
      "verdict": "met",
      "confidence_basis": "The three F1 tests pass on head (missing key/MsgPack004, member type/MsgPack003, allow-private/MsgPack015), and the code reports these diagnostics for suppressed types before the suppress-source-generation early return, confirming no regression in contract-diagnostic reporting; they exercise non-crash paths, while the crash fix is evidenced under N1.",
      "evidence": [
        {"kind": "test", "name": "SuppressSourceGenerationAnalyzerTests.MemberWithoutKeyIsReported", "outcome": "passed"},
        {"kind": "test", "name": "SuppressSourceGenerationAnalyzerTests.MemberTypeMustBeMessagePackObjectIsReported", "outcome": "passed"},
