        {"kind": "code", "file": "src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs", "line": 1383, "rev": "head", "quote": "if (suppressSourceGeneration is true)"}
      ]
    },
    {
      "req": "REQ-2234-F2",
      "verdict": "met",
      "confidence_basis": "The SourceGenerationOnlyDiagnosticsAreNotReportedWhenSuppressed test passes on head expecting zero diagnostics, and the code suppresses AOT-only checks (line 989) and returns before the partial-class check (line 1383) for suppressed types.",
      "evidence": [
        {"kind": "test", "name": "SuppressSourceGenerationAnalyzerTests.SourceGenerationOnlyDiagnosticsAreNotReportedWhenSuppressed", "outcome": "passed"},
        {"kind": "code", "file": "src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs", "line": 989, "rev": "head", "quote": "if (suppressSourceGeneration is not true && isInitOnly)"},
        {"kind": "code", "file": "src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs", "line": 1383, "rev": "head", "quote": "if (suppressSourceGeneration is true)"}
